import sys

def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    moves = data[1:1 + n]
    tx, ty = int(data[1 + n]), int(data[2 + n])
    x = y = 0
    for m in moves:
        if m == 'east':
            x += 1
        elif m == 'west':
            x -= 1
        elif m == 'north':
            y += 1
        else:
            y -= 1
    print('true' if (x, y) == (tx, ty) else 'false')

